		{"negative rate", -1, 1, clock, ErrNonPositiveRate},
		{"zero burst", 1, 0, clock, ErrNonPositiveBurst},
		{"negative burst", 1, -5, clock, ErrNonPositiveBurst},
		{"nil clock", 1, 1, nil, ErrNilClock},
		{"valid", 1, 1, clock, nil},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
