// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// Tokens refill continuously at rate Rate; capacity is Burst.
type Limiter struct {
	mu       sync.Mutex
	rate     float64 // tokens per second
	burst    float64 // max tokens
	tokens   float64 // current tokens
	lastFill time.Time
	clock    Clock
}

// New creates a Limiter with the given refill rate (tokens/sec) and burst
// capacity, starting full. rate and burst must be > 0.
func New(rate float64, burst int) (*Limiter, error) {
	return NewWithClock(rate, burst, realClock{})
}

// NewWithClock is New with an injectable Clock.
func NewWithClock(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be > 0")
	}
	if burst <= 0 {
		return nil, errors.New("ratelimit: burst must be > 0")
	}
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	return &Limiter{
		rate:     rate,
		burst:    float64(burst),
		tokens:   float64(burst),
		lastFill: clock.Now(),
		clock:    clock,
	}, nil
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool { return l.AllowN(1, time.Time{}) }

// AllowN reports whether n tokens may be consumed at time now (pass the
// zero Time to use the clock). It never consumes tokens on failure.
func (l *Limiter) AllowN(n int, now time.Time) bool {
	if now.IsZero() {
		now = l.clock.Now()
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.lastFill).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
		l.lastFill = now
	}
	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// RetryAfter returns the duration until n tokens would be available,
// or 0 if they are available now. n must be > 0.
func (l *Limiter) RetryAfter(n int, now time.Time) time.Duration {
	if now.IsZero() {
		now = l.clock.Now()
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.lastFill).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
		l.lastFill = now
	}
	if float64(n) <= l.tokens {
		return 0
	}
	need := (float64(n) - l.tokens) / l.rate
	return time.Duration(need * float64(time.Second))
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
