func TestNewValidation(t *testing.T) {
	tests := []struct {
		name  string
		rate  float64
		burst int
		clock Clock
		ok    bool
	}{
		{"valid", 1, 1, newFakeClock(time.Time{}), true},
		{"zero rate", 0, 1, newFakeClock(time.Time{}), false},
		{"negative rate", -1, 1, newFakeClock(time.Time{}), false},
		{"zero burst", 1, 0, newFakeClock(time.Time{}), false},
		{"negative burst", 1, -1, newFakeClock(time.Time{}), false},
		{"nil clock", 1, 1, nil, false},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
